    public void VerifyTextWindowResize(List<string> report,string folder){
        LoadImageDocument(Blank(800,500),"Resize text");SetTool("Text");BeginInlineText(NewMark("Text",new PointF(80,90)),true);inlineInput.Text="Keep this text";FlushInlineUpdate();
        var mark=inlineTarget;var size=Size;
        for(int i=0;i<8;i++){RefreshInlinePlacement();if(inlineInput.Font.Height<=0)throw new Exception("Invalid live text font");Size=new Size(1200+i*8,800+i*4);}
        if(inlineTarget!=mark||mark.Text!="Keep this text")throw new Exception("Layout resize lost text");
        View.Zoom=.7f;RefreshInlinePlacement();RefreshInlinePlacement();if(inlineInput.Font.Height<=0)throw new Exception("Invalid zoomed font");
        OnResizeBegin(EventArgs.Empty);if(inlineTarget!=null||inlineInput!=null||Active!=null||SelectedObjects().Count!=0||!Marks.Contains(mark)||mark.Text!="Keep this text")throw new Exception("Resize did not preserve and commit text");
        Size=size;OnResizeEnd(EventArgs.Empty);Undo();if(Marks.Contains(mark))throw new Exception("Resize commit lost undo");Redo();if(!Marks.Any(m=>m.Text=="Keep this text"))throw new Exception("Resize commit lost redo");
