        var legacy=new Mark {Kind="Text",Text="Legacy",Size=22};check(legacy.FontFamily=="Segoe UI"&&TextFonts.Points(legacy.Size)==16.5m,"Legacy text keeps its original appearance with a point-size display");LoadBitmap(Blank(100,100),"Test");
